export function siteCopyFor(language) {
  return SITE_UI_COPY[language] ?? SITE_UI_COPY.en;
}

export function localizeJourneyItem(item, index, language) {
  const translation = SITE_UI_COPY[language]?.journey.steps[index];
  return translation ? { ...item, ...translation } : item;
}

export function localizeArticle(item, language) {
  const translation = SITE_UI_COPY[language]?.journal.articles[item.id];
  return translation ? { ...item, ...translation } : item;
}
